export async function createScene(engine, canvas, BABYLON) {
  console.clear();
  const scene = new BABYLON.Scene(engine);
  scene.clearColor = new BABYLON.Color4(0.61, 0.68, 0.53, 1);
  scene.useRightHandedSystem = true;

  var camera = new BABYLON.ArcRotateCamera("camera", BABYLON.Tools.ToRadians(90), BABYLON.Tools.ToRadians(65), 10, BABYLON.Vector3.Zero(), scene);
  camera.setTarget(new BABYLON.Vector3(0, 1.2, 0));
  camera.alpha = 0.89;
  camera.beta = 0.89;
  camera.radius = 55;
  camera.inertia = 0.4;
  camera.wheelDeltaPercentage = 0.3;
  camera.panningSensibility = 10000;
  camera.minZ = 0.01;
  camera.maxZ = 10000;
  camera.attachControl(canvas, true);

  var light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);

  scene.enablePhysics(new BABYLON.Vector3(0, -30, 0), new BABYLON.AmmoJSPlugin());

  let rootMesh;

  BABYLON.SceneLoader.ImportMeshAsync("", "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/", "billiards_pool.glb").then((result) => {
    rootMesh = result.meshes[0];

    const plane = rootMesh.getChildMeshes(false, (m) => m.name === "Cylinder.005_Material.003_0")[0];
    plane.physicsImpostor = new BABYLON.PhysicsImpostor(plane, BABYLON.PhysicsImpostor.BoxImpostor, { mass: 0, friction: 0.8 }, scene);
    plane.physicsImpostor.forceUpdate();

    const projectile = BABYLON.MeshBuilder.CreateSphere("projectile", { diameter: 0.5 }, scene);
    projectile.material = new BABYLON.StandardMaterial("projMat", scene);
    projectile.material.diffuseColor = BABYLON.Color3.Red();
    projectile.position.set(0, 15, 0);

    projectile.physicsImpostor = new BABYLON.PhysicsImpostor(
      projectile,
      BABYLON.PhysicsImpostor.SphereImpostor,
      { mass: 1, restitution: 0.5, friction: 0.8 },
      scene
    );
    projectile.actionManager = new BABYLON.ActionManager(scene);

    projectile.actionManager.registerAction(new BABYLON.ExecuteCodeAction(BABYLON.ActionManager.OnPointerOverTrigger, () => {}));

    rootMesh
      .getChildMeshes(false, (m) => m.name.includes("Wall"))
      .forEach((mesh) => {
        mesh.physicsImpostor = new BABYLON.PhysicsImpostor(
          mesh,
          BABYLON.PhysicsImpostor.BoxImpostor,
          { mass: 0, restitution: 1, friction: 0.5 },
          scene
        );
        mesh.physicsImpostor.forceUpdate();
      });

    scene.onPointerObservable.add((pointerInfo) => {
      if (pointerInfo.type === BABYLON.PointerEventTypes.POINTERDOWN) {
        const pickResult = scene.pick(scene.pointerX, scene.pointerY);
        if (pickResult.hit && pickResult.pickedMesh === projectile) {
          const cameraDirection = camera.getForwardRay().direction;
          const impulseStrength = 30;
          projectile.physicsImpostor.applyImpulse(cameraDirection.scale(impulseStrength), projectile.getAbsolutePosition());
        }
      }
    });

    var radiusAnimation = new BABYLON.Animation(
      "radiusAnimation",
      "radius",
      30,
      BABYLON.Animation.ANIMATIONTYPE_FLOAT,
      BABYLON.Animation.ANIMATIONLOOPMODE_CONSTANT
    );
    var radiusKeys = [];
    radiusKeys.push({ frame: 0, value: camera.radius });
    radiusKeys.push({ frame: 60, value: 41 });
    radiusAnimation.setKeys(radiusKeys);

    var targetAnimation = new BABYLON.Animation(
      "targetAnimation",
      "target",
      30,
      BABYLON.Animation.ANIMATIONTYPE_VECTOR3,
      BABYLON.Animation.ANIMATIONLOOPMODE_CONSTANT
    );
    var targetKeys = [];
    targetKeys.push({ frame: 0, value: camera.target });
    targetKeys.push({ frame: 60, value: rootMesh.position.add(new BABYLON.Vector3(0, 2, 0)) });
    targetAnimation.setKeys(targetKeys);

    camera.animations.push(radiusAnimation);
    camera.animations.push(targetAnimation);

    setTimeout(() => {
      scene.beginAnimation(camera, 0, 60, false);
    }, 1500);
  });

  return scene;
}
